import ast, os, sys, collections
root=sys.argv[1]
defs=collections.defaultdict(list)  # name -> [(file, line, bases)]
for dp,dn,fn in os.walk(root):
    dn[:]=[d for d in dn if d not in('node_modules','.git','graphify-out')]
    for f in fn:
        if not f.endswith('.py'): continue
        p=os.path.join(dp,f)
        try: t=ast.parse(open(p,encoding='utf-8').read())
        except Exception as e: print("ERR",p,e,file=sys.stderr); continue
        for n in ast.walk(t):
            if isinstance(n,ast.ClassDef):
                bs=[]
                for b in n.bases:
                    if isinstance(b,ast.Name): bs.append(b.id)
                    elif isinstance(b,ast.Attribute): bs.append(b.attr)
                defs[n.name].append((os.path.relpath(p,root),n.lineno,bs))
found={'StockController'};changed=True
res={}
while changed:
    changed=False
    for name,lst in defs.items():
        for (p,l,bs) in lst:
            if any(b in found for b in bs) and (name,p) not in res:
                res[(name,p)]=(l,bs); 
                if name not in found: found.add(name)
                changed=True
for (name,p),(l,bs) in sorted(res.items(),key=lambda x:x[0][1]):
    test = '/test' in p or os.path.basename(p).startswith('test_')
    print(('TEST ' if test else '     ')+f"{name} ({', '.join(bs)}) -- {p}:{l}")
EOF
